"""Replay the TypeScript engine's vectors (vectors.json, generated by test/pythonParity.test.ts) against the Python port."""

import json
import math
import unittest
from pathlib import Path

from redcap_display import Engine
from redcap_display.logic import LogicFieldRef, evaluate_logic, js_number_to_string, parse_logic

PAYLOAD = json.loads((Path(__file__).parent / "vectors.json").read_text(encoding="utf-8"))


def reference_key(ref: LogicFieldRef) -> str:
    return (ref.event + ":" if ref.event else "") + ref.name + ("(" + ref.code + ")" if ref.code else "")


class _TableLookup:
    def __init__(self, fields, smart, today):
        self._fields = fields
        self._smart = smart
        self._today = today

    def field(self, ref):
        return self._fields.get(reference_key(ref))

    def smart(self, name):
        return self._smart.get(name)

    def today(self):
        return self._today


def comparable(value):
    """A value tagged with its kind. JSON has no float/int split, and the vectors store non-finite numbers as text."""
    if value is None:
        return None
    if isinstance(value, bool):
        return ("boolean", value)
    if isinstance(value, (int, float)):
        return ("number", float(value)) if math.isfinite(value) else ("string", js_number_to_string(float(value)))
    return ("string", value)


class ConditionParity(unittest.TestCase):
    def test_conditions_match_typescript(self):
        failures = []
        for vector in PAYLOAD["conditions"]:
            result = evaluate_logic(parse_logic(vector["expression"]), _TableLookup(vector["fields"], vector["smart"], vector["today"]))
            actual = (comparable(result.value), result.missing, result.unsupported)
            expected = (comparable(vector["value"]), vector["missing"], vector["unsupported"])
            if actual != expected:
                failures.append((vector["expression"], vector["fields"].get("a"), expected, actual))
        self.assertEqual(failures[:20], [], "%d of %d conditions disagree" % (len(failures), len(PAYLOAD["conditions"])))


class VisibilityParity(unittest.TestCase):
    def test_visibility_matches_typescript(self):
        engines = {name: Engine(parsed) for name, parsed in PAYLOAD["projects"].items()}
        failures = []
        for index, vector in enumerate(PAYLOAD["visibility"]):
            actual = engines[vector["project"]].evaluate(vector["context"])
            expected = vector["expected"]
            if actual != expected or list(actual) != list(expected):
                differing = [key for key in expected if actual.get(key) != expected[key]]
                failures.append((index, vector["project"], vector["context"]["event"], vector["context"]["mode"], differing[:3]))
        self.assertEqual(failures[:10], [], "%d of %d contexts disagree" % (len(failures), len(PAYLOAD["visibility"])))


if __name__ == "__main__":
    unittest.main()
